ilover:"Suspend ASUS rule effect during failover",restoreAsusRulesOnRecovery:"Restore ASUS rules after recovery",rememberedDualWanPreset:"Normal Dual WAN preset",rememberedDualWanPresetHint:"Optional. Name of the Dual WAN preset SmartWAN should treat as the normal profile to restore after recovery.",primaryWan:"Primary WAN",failoverWan:"Failover WAN",manageMainDefault:"Manage main default route",googlePolicyTemplate:"Google via WAN1 template",popularTemplates:"Popular templates",priorityDomains:"Domains / marks",priorityDestinations:"Destination CIDR",prioritySources:"Source devices",priorityDefault:"Primary/failover default",addBlock:"Add block",removeBlock:"Remove block",noRulesInGroup:"No blocks in this group.",wanOverview:"WAN network overview",activeDefault:"Active default",wanIp:"WAN IP",publicIp:"Public IP",publicIpNoTool:"Unavailable on router",publicIpProbeFailed:"Probe failed",publicIpPanelDefault:"Panel probe: default route",publicIpPanelGoogle:"Panel probe: Google path",publicIpRouterNvram:"Router NVRAM",publicIpRouterProbe:"Router probe",publicIpLastConfirmed:"Last confirmed for this WAN",wanCableOrLink:"Link",wanDhcpOrIp:"DHCP / IP",wanInternet:"Internet",internetOk:"reachable",internetFailed:"no internet",internetNoIp:"no WAN IP",internetNoInterface:"no interface",internetOverridden:"failover override",internetNotChecked:"not checked",internetProbe:"probe",up:"up",down:"down",detected:"detected",notDetected:"Not detected",gateway:"Gateway",sourceIp:"Source IP",state:"State",noWanDefaultRoute:"No default route in this WAN table.",watchdog:"Watchdog",running:"running",stopped:"stopped",merlinHooks:"Merlin hooks",installed:"installed",notInstalled:"not installed",recentLog:"Recent SmartWAN log",currentRoutes:"Current routes and rules",enabled:"Enabled",disabled:"Disabled",wanLabels:"WAN labels",wan0Label:"WAN0 label",wan1Label:"WAN1 label",routingDetails:"Routing details",wan0Ifname:"WAN0 interface",wan1Ifname:"WAN1 interface",wan0Gateway:"WAN0 gateway",